double GL(double T, double xl[], int nsolutes) {
    double XCRL, XFEL, XMOL, XNBL, XTIL;
    double gliq;
    
    XCRL = xl[0];
    XFEL = xl[1];
    XMOL = xl[2];
    XNBL = xl[3];
    XTIL = xl[4];
    
    gliq = GLIQ(T, XCRL, XFEL, XMOL, XNBL, XTIL);
    
    return gliq;
}
double GS(double T, double xs[], int nsolutes) { 
    double XCRS, XFES, XMOS, XNBS, XTIS;
    double gsol;
    
    XCRS = xs[0];
    XFES = xs[1];
    XMOS = xs[2];
    XNBS = xs[3];
    XTIS = xs[4];
    
    gsol = GFCC(T, XCRS, XFES, XMOS, XNBS, XTIS);
    
    return gsol;
}

double dGLdXL(double T, double xl[], int nsolutes, int counter) { 
    double XCRL, XFEL, XMOL, XNBL, XTIL;
    double dgldxl = 0.0f;
    
    XCRL = xl[0];
    XFEL = xl[1];
    XMOL = xl[2];
    XNBL = xl[3];
    XTIL = xl[4];
    
    if ( counter == 0 ) {
        dgldxl = dGLIQdXCRL(T, XCRL, XFEL, XMOL, XNBL, XTIL);
    }
    else if ( counter == 1 ) {
        dgldxl = dGLIQdXFEL(T, XCRL, XFEL, XMOL, XNBL, XTIL);
    }
    else if ( counter == 2 ) {
        dgldxl = dGLIQdXMOL(T, XCRL, XFEL, XMOL, XNBL, XTIL);
    }
    else if ( counter == 3 ) {
        dgldxl = dGLIQdXNBL(T, XCRL, XFEL, XMOL, XNBL, XTIL);
    }
    else if ( counter == 4 ) {
        dgldxl = dGLIQdXTIL(T, XCRL, XFEL, XMOL, XNBL, XTIL);
    }
    return dgldxl;
}
